import { HubConnectionBuilder, HubConnection } from '@microsoft/signalr';
import { fromWire, toWire } from '../helpers/wireNames';
import type { Device, LogLine } from '../models';

export type LogsHubConnectionState = 'Disconnected' | 'Connecting' | 'Connected' | 'Reconnecting';

export interface LogsHubCallbacks {
  onLogLine?: (event: LogLine) => void;
  onDeviceUpdated?: (event: Device) => void;
  onPing?: (event: unknown) => void;
}

/**
 * A connection to the logs hub (not started): each event goes to its callback, read when
 * the event arrives.
 */
export function createLogsHubConnection(baseUrl: string, callbacks: () => LogsHubCallbacks): HubConnection {
  const connection = new HubConnectionBuilder()
    .withUrl(`${baseUrl}/hubs/logs`)
    .withAutomaticReconnect()
    .build();

  connection.on('LogLine', (event: unknown) => {
    callbacks().onLogLine?.(fromWire<LogLine>(event, 'LogLine'));
  });
  connection.on('device-updated', (event: unknown) => {
    callbacks().onDeviceUpdated?.(fromWire<Device>(event, 'Device'));
  });
  connection.on('Ping', (event: unknown) => {
    callbacks().onPing?.(event);
  });

  return connection;
}

export interface LogsHubMethods {
  subscribe(payload: string[]): Promise<string>;
  getRecent(payload: number): Promise<LogLine[]>;
  annotateDevice(payload: Device): Promise<boolean>;
  clear(): Promise<void>;
  moveDevice(deviceId: string, connection2: Device, deleteValue: boolean): Promise<LogLine>;
}

/**
 * The logs hub's methods over a started connection: each invokes the method under its name on
 * the wire and resolves with its answer.
 */
export function logsHubMethods(connection: Pick<HubConnection, 'invoke'>): LogsHubMethods {
  return {
    subscribe: (payload: string[]) => connection.invoke<string>('Subscribe', payload),
    getRecent: (payload: number) => connection.invoke<unknown>('GetRecent', payload).then((answer) => fromWire<LogLine[]>(answer, { array: 'LogLine' })),
    annotateDevice: (payload: Device) => connection.invoke<boolean>('annotate-device', toWire(payload, 'Device')),
    clear: () => connection.invoke<void>('Clear'),
    moveDevice: (deviceId: string, connection2: Device, deleteValue: boolean) => connection.invoke<unknown>('MoveDevice', deviceId, toWire(connection2, 'Device'), deleteValue).then((answer) => fromWire<LogLine>(answer, 'LogLine')),
  };
}